import difflib
import hashlib
import json
import platform
import posixpath
import sys
import xml.etree.ElementTree as ET
import zipfile
from datetime import datetime
from pathlib import Path
from urllib.parse import unquote

root = Path(sys.argv[1])
out = root / "Research/studies/author-semantics/data/kpol-syntax-157"
audit = json.loads((out / "source-delta-01.json").read_text())
ns = {"p": "http://schemas.openxmlformats.org/presentationml/2006/main"}
result = {
    "timestamp": datetime.now().astimezone().isoformat(),
    "host": platform.node(), "base_commit": audit["base_commit"],
    "command": ["python3", *sys.argv],
    "reproducer_source": Path(__file__).read_text(),
    "packages": {}, "matching_paragraph_direct_baseline_changes": [],
    "baseline_limit": "Direct run baseline, zero when absent; matching paragraph text only. Not a complete style cascade or renderer.",
}


def target(rel_part, name):
    base = "" if rel_part == "_rels/.rels" else posixpath.dirname(posixpath.dirname(rel_part))
    return unquote(name.lstrip("/") if name.startswith("/") else posixpath.normpath(base + "/" + name).lstrip("/"))


for which in ("old", "new"):
    deck = audit[which]
    with zipfile.ZipFile(root / deck["path"]) as archive:
        parts = set(archive.namelist())
        xml_count, missing, external = 0, [], []
        slide_for_comment = {}
        for slide in deck["slides"]:
            part = slide["part"]
            rel_part = posixpath.dirname(part) + "/_rels/" + posixpath.basename(part) + ".rels"
            for rel in ET.fromstring(archive.read(rel_part)):
                if rel.get("Type", "").endswith("/comments"):
                    slide_for_comment[target(rel_part, rel.get("Target"))] = slide["number"]
        for part in sorted(parts):
            if part.endswith((".xml", ".rels")):
                doc = ET.fromstring(archive.read(part))
                xml_count += 1
                if part.endswith(".rels"):
                    for rel in doc:
                        if rel.get("TargetMode") == "External":
                            external.append({"part": part, "target": rel.get("Target")})
                        elif target(part, rel.get("Target")) not in parts:
                            missing.append({"part": part, "target": rel.get("Target")})
        authors_doc = ET.fromstring(archive.read("ppt/commentAuthors.xml"))
        authors = {a.get("id"): a.get("name") for a in authors_doc}
        comments = []
        for part in sorted(p for p in parts if p.startswith("ppt/comments/") and p.endswith(".xml")):
            for comment in ET.fromstring(archive.read(part)):
                comments.append({
                    "part": part, "slide": slide_for_comment.get(part),
                    "author_id": comment.get("authorId"),
                    "author_name": authors.get(comment.get("authorId")),
                    "date": comment.get("dt"),
                    "text": comment.find("p:text", ns).text,
                })
        result["packages"][which] = {
            "xml_and_rels_parsed": xml_count,
            "missing_internal_targets": missing,
            "external_relationships_not_fetched": external,
            "comment_authors": authors, "comments": comments,
        }
        assert not missing


def canonical(slide):
    return {
        p["paragraph"]: [(c, r["baseline"]) for r in p["runs"] for c in r["text"]]
        for p in slide["styled_paragraphs"]
    }


for old, new in zip(audit["old"]["slides"], audit["new"]["slides"]):
    a, b = canonical(old), canonical(new)
    for match in difflib.SequenceMatcher(a=old["paragraphs"], b=new["paragraphs"], autojunk=False).get_matching_blocks():
        for i, j in zip(range(match.a, match.a + match.size), range(match.b, match.b + match.size)):
            before = a.get(i + 1, [(c, 0) for c in old["paragraphs"][i]])
            after = b.get(j + 1, [(c, 0) for c in new["paragraphs"][j]])
            if before != after:
                result["matching_paragraph_direct_baseline_changes"].append({
                    "slide": old["number"], "old_paragraph": i + 1, "new_paragraph": j + 1,
                    "old": before, "new": after,
                })
result["comment_meaning_fields_unchanged"] = (
    sorted((c["slide"], c["author_name"], c["text"]) for c in result["packages"]["old"]["comments"])
    == sorted((c["slide"], c["author_name"], c["text"]) for c in result["packages"]["new"]["comments"])
)
with (out / "package-supplement-01.json").open("x") as handle:
    json.dump(result, handle, ensure_ascii=False, indent=2)
    handle.write("\n")
print(json.dumps({
    "xml_counts": {k: v["xml_and_rels_parsed"] for k, v in result["packages"].items()},
    "missing_targets": {k: v["missing_internal_targets"] for k, v in result["packages"].items()},
    "normalized_baseline_changes": result["matching_paragraph_direct_baseline_changes"],
    "comment_meaning_fields_unchanged": result["comment_meaning_fields_unchanged"],
}))
